import { t, msg, labelMap } from '../../i18n';
import { z } from 'zod';
import { apiGet, apiWrite } from './adapter';
import { ServiceError } from '../contracts';
import type { Person } from '../../models/domain';

/**
 * Every notification type a user can receive. The last four are generated by the system only:
 * they are not routable and have no preference, so rule/preference forms keep `notificationTypes`.
 */
export const inboxTypes = [
  'FallDetected',
  'EmergencyManual',
  'GeofenceBreach',
  'ArrivalNotification',
  'SystemAlert',
  'LicenseExpiryWarning',
  'EscalationSuggestion',
  'EmergencyUnreachable',
  'PaymentSuccess',
  'LicenseRenewalReminder',
] as const;
export const inboxTypeLabels: Record<string, string> = labelMap({
  FallDetected: msg('Phát hiện té ngã'),
  EmergencyManual: msg('Khẩn cấp chủ động'),
  GeofenceBreach: msg('Vượt vùng an toàn'),
  ArrivalNotification: msg('Thông báo đến nơi'),
  SystemAlert: msg('Thông báo hệ thống'),
  LicenseExpiryWarning: msg('Cảnh báo license sắp hết hạn'),
  EscalationSuggestion: msg('Gợi ý gọi hỗ trợ khẩn cấp'),
  EmergencyUnreachable: msg('Không liên hệ được ai'),
  PaymentSuccess: msg('Thanh toán thành công'),
  LicenseRenewalReminder: msg('Nhắc gia hạn license'),
});
export const deliveryChannelLabels: Record<string, string> = {
  Fcm: 'Push',
  Email: 'Email',
  SignalR: 'Realtime',
};
export const deliveryStatusLabels: Record<string, string> = labelMap({
  Pending: msg('Đang chờ gửi'),
  Sent: msg('Đã gửi'),
  Failed: msg('Gửi thất bại'),
});
const uuid = z.string().uuid();
const time = z.iso.datetime({ offset: true });
const paged = <T extends z.ZodType>(item: T) =>
  z.object({
    items: z.array(item),
    page: z.number().int().positive(),
    pageSize: z.number().int().positive(),
    totalCount: z.number().int().nonnegative(),
    totalPages: z.number().int().nonnegative(),
    hasNextPage: z.boolean(),
    hasPreviousPage: z.boolean(),
  });
const inboxItem = z.object({
  id: uuid,
  notificationType: z.string(),
  sourceType: z.string(),
  emergencyEventId: uuid.nullable(),
  locationBoundaryEventId: uuid.nullable(),
  visuallyImpairedUserId: uuid.nullable(),
  visuallyImpairedUserName: z.string().nullable(),
  title: z.string().nullable(),
  body: z.string().nullable(),
  deliveries: z.array(z.string()),
  createdAt: time,
  sentAt: time.nullable(),
  readAt: time.nullable(),
});
export type InboxItem = z.infer<typeof inboxItem>;
const delivery = z.object({
  id: uuid,
  notificationType: z.string(),
  sourceType: z.string(),
  channel: z.string(),
  status: z.string(),
  recipientId: uuid,
  recipientName: z.string().nullable(),
  recipientRole: z.string().nullable(),
  visuallyImpairedUserId: uuid.nullable(),
  visuallyImpairedUserName: z.string().nullable(),
  caregiverLinkId: uuid.nullable(),
  emergencyEventId: uuid.nullable(),
  locationBoundaryEventId: uuid.nullable(),
  title: z.string().nullable(),
  body: z.string().nullable(),
  failureReason: z.string().nullable(),
  retryCount: z.number().int().nonnegative(),
  createdAt: time,
  sentAt: time.nullable(),
  readAt: time.nullable(),
});
export type NotificationDelivery = z.infer<typeof delivery>;
export type InboxFilters = {
  viuId?: string;
  type?: string;
  from?: string;
  to?: string;
  unreadOnly?: boolean;
  page?: number;
};
export type LookupFilters = {
  recipientId?: string;
  viuId?: string;
  type?: string;
  channel?: string;
  status?: string;
  from?: string;
  to?: string;
  page?: number;
};
/** "Fcm:Sent" → { channel: 'Fcm', status: 'Sent' }. */
export function parseDelivery(value: string) {
  const [channel = '', status = ''] = value.split(':');
  return { channel, status };
}
function parse<T>(schema: z.ZodType<T>, raw: unknown): T {
  const result = schema.safeParse(raw);
  if (!result.success)
    throw new ServiceError(
      t('Dữ liệu thông báo không hợp lệ. Kiểm tra các trường và tải lại.'),
      502,
    );
  return result.data;
}
// Vietnam day bounds sent as UTC instants (the BE filters on timestamptz).
const dayStart = (day: string) => new Date(`${day}T00:00:00+07:00`).toISOString();
const dayEnd = (day: string) => new Date(`${day}T23:59:59.999+07:00`).toISOString();
function dates(query: URLSearchParams, from?: string, to?: string) {
  if ([from, to].some((d) => d && !z.iso.date().safeParse(d).success) || (from && to && from > to))
    throw new ServiceError(t('Khoảng ngày không hợp lệ. Kiểm tra ngày bắt đầu và kết thúc.'), 400);
  if (from) query.set('dateFrom', dayStart(from));
  if (to) query.set('dateTo', dayEnd(to));
}
function id(value: string | undefined, query: URLSearchParams, key: string) {
  if (!value) return;
  if (!uuid.safeParse(value).success) throw new ServiceError(t('Bộ lọc không hợp lệ.'), 400);
  query.set(key, value);
}
export function createInboxApi(get = apiGet, write = apiWrite) {
  return {
    async list(filters: InboxFilters, signal?: AbortSignal) {
      const query = new URLSearchParams({ page: String(filters.page ?? 1), pageSize: '20' });
      id(filters.viuId, query, 'viuId');
      if (filters.type) query.set('type', filters.type);
      if (filters.unreadOnly) query.set('unreadOnly', 'true');
      dates(query, filters.from, filters.to);
      return parse(paged(inboxItem), await get('/api/notifications/inbox?' + query, signal));
    },
    async unreadCount(viuId?: string, signal?: AbortSignal) {
      const query = new URLSearchParams();
      id(viuId, query, 'viuId');
      const suffix = query.size ? '?' + query : '';
      return parse(
        z.number().int().nonnegative(),
        await get('/api/notifications/inbox/unread-count' + suffix, signal),
      );
    },
    async markRead(item: Pick<InboxItem, 'id'>) {
      if (!uuid.safeParse(item.id).success)
        throw new ServiceError(t('Thông báo không hợp lệ.'), 400);
      await write('/api/notifications/' + item.id + '/read', { method: 'PATCH' });
    },
    async markAllRead(viuId?: string) {
      const query = new URLSearchParams();
      id(viuId, query, 'viuId');
      const raw = await write('/api/notifications/read-all' + (query.size ? '?' + query : ''), {
        method: 'PATCH',
      });
      const count = z.number().int().nonnegative().safeParse(raw);
      return count.success ? count.data : 0;
    },
    /** Super Admin: every delivery. Center Admin: recipients or VIUs of their organization. */
    async lookup(
      actor: Pick<Person, 'role' | 'orgId'>,
      filters: LookupFilters,
      signal?: AbortSignal,
    ) {
      if (actor.role !== 'Admin' && (actor.role !== 'CenterAdmin' || !actor.orgId))
        throw new ServiceError(t('Chỉ quản trị viên được tra cứu thông báo.'), 403);
      const query = new URLSearchParams({ page: String(filters.page ?? 1), pageSize: '20' });
      id(filters.recipientId, query, 'recipientId');
      id(filters.viuId, query, 'viuId');
      for (const key of ['type', 'channel', 'status'] as const)
        if (filters[key]) query.set(key, filters[key]);
      dates(query, filters.from, filters.to);
      return parse(paged(delivery), await get('/api/notifications?' + query, signal));
    },
  };
}
export const inboxApi = createInboxApi();
